package com.dairy;
import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.transaction.annotation.Transactional;import com.dairy.service.DairyService;import com.dairy.dto.Requests.*;import java.math.BigDecimal;import java.time.LocalDate;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:test;MODE=MySQL","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password="}) @Transactional @org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
class DairyIntegrationTest {
@Autowired DairyService s;
@Autowired org.springframework.test.web.servlet.MockMvc mvc;
@Test void endpoints() throws Exception {for(String endpoint:new String[]{"/api/farmers","/api/rates","/api/dashboard","/api/collections","/api/reports?month=2026-10"})mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(endpoint)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());}
@Test void rounding(){assertEquals(new BigDecimal("10.01"),DairyService.amount(new BigDecimal("1.001"),new BigDecimal("10")));}
@Test void workflow(){var f=s.farmer(null,new FarmerInput("Test Farmer","9000000001","Test Village"));var r=s.rate(null,new RateInput("COW",new BigDecimal("3.50"),new BigDecimal("8.50"),new BigDecimal("35")));var c=s.collect(new CollectionInput(f.id,LocalDate.now(),"MORNING","COW",new BigDecimal("2.500"),new BigDecimal("3.5"),new BigDecimal("8.5")));assertEquals(new BigDecimal("87.50"),c.amount);s.rate(r.id,new RateInput("COW",r.fat,r.snf,new BigDecimal("40")));assertEquals(new BigDecimal("87.50"),s.entries(LocalDate.now().toString().substring(0,7),f.id).get(0).amount);assertThrows(Exception.class,()->s.deleteFarmer(f.id));assertThrows(Exception.class,()->s.rate(null,new RateInput("COW",r.fat,r.snf,new BigDecimal("20"))));assertThrows(Exception.class,()->s.collect(new CollectionInput(f.id,LocalDate.now(),"EVENING","BUFFALO",BigDecimal.ONE,r.fat,r.snf)));assertEquals(new BigDecimal("87.50"),s.report(LocalDate.now().toString().substring(0,7)).get(0).get("amount"));}
}
